import 'package:flutter/material.dart';
import '../data/registration_service.dart';
class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key,required this.service}); final RegistrationService service; @override State<RegisterScreen> createState()=>_RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen>{ final form=GlobalKey<FormState>(); final name=TextEditingController(),email=TextEditingController(),password=TextEditingController(),confirm=TextEditingController(),dob=TextEditingController(),guardian=TextEditingController(),guardianPhone=TextEditingController(); bool loading=false; String? message; bool get minor { final d=DateTime.tryParse(dob.text); if(d==null)return false; final now=DateTime.now(); int age=now.year-d.year-((now.month<d.month||(now.month==d.month&&now.day<d.day))?1:0); return age<18; }
Future<void> submit() async { if(!form.currentState!.validate())return; setState(()=>loading=true); try{final r=await widget.service.register({'name':name.text.trim(),'email':email.text.trim(),'password':password.text,'password_confirmation':confirm.text,'date_of_birth':dob.text.trim(),if(minor)'guardian_name':guardian.text.trim(),if(minor)'guardian_relationship':'Guardian',if(minor)'guardian_phone':guardianPhone.text.trim()}); if(mounted)setState(()=>message=r['message']?.toString());}catch(_){if(mounted)setState(()=>message='Registration could not be completed. Please check your details and try again.');}finally{if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create account')),body:SafeArea(child:Form(key:form,child:ListView(padding:const EdgeInsets.all(20),children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Full name'),validator:(v)=>v==null||v.trim().isEmpty?'Required':null),TextFormField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email'),validator:(v)=>v==null||!v.contains('@')?'Enter a valid email':null),TextFormField(controller:dob,decoration:const InputDecoration(labelText:'Date of birth (YYYY-MM-DD)'),onChanged:(_)=>setState((){}),validator:(v)=>DateTime.tryParse(v??'')==null?'Use YYYY-MM-DD':null),if(minor)...[TextFormField(controller:guardian,decoration:const InputDecoration(labelText:'Parent/guardian name'),validator:(v)=>minor&&(v==null||v.trim().isEmpty)?'Required for teens':null),TextFormField(controller:guardianPhone,decoration:const InputDecoration(labelText:'Parent/guardian phone'),validator:(v)=>minor&&(v==null||v.trim().isEmpty)?'Required for teens':null)],TextFormField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password'),validator:(v)=>(v??'').length<8?'Use at least 8 characters':null),TextFormField(controller:confirm,obscureText:true,decoration:const InputDecoration(labelText:'Confirm password'),validator:(v)=>v!=password.text?'Passwords do not match':null),const SizedBox(height:20),Semantics(button:true,label:'Create Church of Uganda Youth Platform account',child:FilledButton(onPressed:loading?null:submit,child:Text(loading?'Creating account…':'Create account'))),if(message!=null)Padding(padding:const EdgeInsets.only(top:16),child:Text(message!,textAlign:TextAlign.center))])))); }
